mod support;

use std::sync::Arc;

use maho_agent::harness::context::BACKGROUND_CONTEXT;
use maho_agent::harness::env::nodejs::NodeExecutionEnv;
use maho_agent::harness::session::jsonl::{JsonlSessionRepo, JsonlSessionRepoOptions, JsonlStorage, JsonlStorageOptions, JSONL_STORAGE_VERSION};
use maho_agent::harness::session::jsonl::types::{JsonlSessionListOptions};
use maho_agent::harness::session::types::{EntryQuery, EntryScan, ScanOrder, Session, Storage};
use maho_agent::harness::session::values::{branch_tip, lane_config, lane_state, session_name};
use maho_agent::harness::types::FileSystem;
use serde_json::{json, Value};

const NOW: i64 = 1_700_000_000_000;

fn root(label: &str) -> String {
    let p = std::env::temp_dir().join(format!("maho-jsonl-v3-{label}-{}-{}", std::process::id(), support::unique_suffix()));
    std::fs::create_dir_all(&p).expect("temp root");
    p.to_string_lossy().into_owned()
}
fn fs(root: &str) -> Arc<dyn FileSystem> { Arc::new(NodeExecutionEnv::new(root.to_owned())) }
fn repo(f: Arc<dyn FileSystem>) -> JsonlSessionRepo { JsonlSessionRepo::new(JsonlSessionRepoOptions { file_system: f, sessions_root: "sessions".into(), now: Some(Arc::new(|| NOW)) }) }
fn iso(t: i64) -> String { if t == NOW { "2023-11-14T22:13:20.000Z".into() } else { format!("2023-11-14T22:13:{}.{:03}Z", 20 + ((t-NOW)/1000), (t-NOW)%1000) } }

async fn fixture(f: &Arc<dyn FileSystem>, records: &[Value], parent: Option<&str>) -> (String, String) {
    let dir = f.join_path(vec!["sessions".into(), "--workspace--".into()], &BACKGROUND_CONTEXT).await.expect("join");
    f.create_dir(&dir, None, &BACKGROUND_CONTEXT).await.expect("dir");
    let path = f.absolute_path(&format!("{dir}/legacy.jsonl"), &BACKGROUND_CONTEXT).await.expect("path");
    let mut all = vec![json!({"type":"session","version":3,"id":"legacy","timestamp":iso(NOW),"cwd":"/workspace"})];
    if let Some(p) = parent { all[0]["parentSession"] = json!(p); }
    all.extend_from_slice(records);
    let content = all.iter().map(Value::to_string).collect::<Vec<_>>().join("\n") + "\n";
    f.write_file(&path, content.as_bytes(), &BACKGROUND_CONTEXT).await.expect("write");
    (path, content)
}
async fn metadata(r: &JsonlSessionRepo) -> maho_agent::harness::session::jsonl::JsonlSessionMetadata {
    r.list(Some(JsonlSessionListOptions { cwd: Some("/workspace".into()) }), &BACKGROUND_CONTEXT).await.expect("list").into_iter().next().expect("metadata")
}
fn user(text: &str, timestamp: i64) -> Value { json!({"role":"user","content":[{"type":"text","text":text}],"timestamp":timestamp}) }
fn msg(id: &str, parent: Option<&str>, text: &str, timestamp: i64) -> Value { json!({"type":"message","id":id,"parentId":parent,"timestamp":iso(timestamp),"message":user(text,timestamp)}) }
fn model(id: &str, parent: &str, provider: &str, model: &str, timestamp: i64) -> Value { json!({"type":"model_change","id":id,"parentId":parent,"timestamp":iso(timestamp),"provider":provider,"modelId":model}) }
fn thinking(id: &str, parent: &str, level: &str, timestamp: i64) -> Value { json!({"type":"thinking_level_change","id":id,"parentId":parent,"timestamp":iso(timestamp),"thinkingLevel":level}) }

#[tokio::test] async fn discovers_legacy_v3_without_rewriting() {
    let r=root("discover"); let f=fs(&r); let (path, content)=fixture(&f,&[],Some("/old-session.jsonl")).await; let m=metadata(&repo(f.clone())).await;
    assert_eq!(m.id,"legacy"); assert_eq!(m.created_at,NOW); assert_eq!(m.storage_version,JSONL_STORAGE_VERSION); assert_eq!(m.cwd,"/workspace"); assert_eq!(m.path,path); assert_eq!(m.legacy_parent_session_path.as_deref(),Some("/old-session.jsonl")); assert!(m.modified_at>0); assert_eq!(f.read_text_file(&path,&BACKGROUND_CONTEXT).await.expect("read"),content); std::fs::remove_dir_all(r).expect("cleanup");
}

async fn parent_case(label:&str, header:Value, expected:&str) { let r=root(label); let f=fs(&r); let p=f.absolute_path(&format!("parent-{label}.jsonl"),&BACKGROUND_CONTEXT).await.expect("path"); f.write_file(&p,format!("{}\n",header).as_bytes(),&BACKGROUND_CONTEXT).await.expect("parent"); fixture(&f,&[],Some(&p)).await; let m=metadata(&repo(f.clone())).await; assert_eq!(m.parent_session_id.as_deref(),Some(expected)); assert!(m.legacy_parent_session_path.is_none()); std::fs::remove_dir_all(r).expect("cleanup"); }
#[tokio::test] async fn resolves_v3_parent_id(){parent_case("v3",json!({"type":"session","version":3,"id":"legacy-parent","timestamp":iso(NOW),"cwd":"/workspace"}),"legacy-parent").await}
#[tokio::test] async fn resolves_v4_parent_id(){parent_case("v4",json!({"v":4,"kind":"header","id":"current-parent","storageVersion":1,"createdAt":NOW,"cwd":"/workspace"}),"current-parent").await}
#[tokio::test] async fn preserves_invalid_parent_path(){let r=root("invalid");let f=fs(&r);let p=f.absolute_path("invalid-parent.jsonl",&BACKGROUND_CONTEXT).await.expect("path");f.write_file(&p,b"{\"not\":\"a session header\"}\n",&BACKGROUND_CONTEXT).await.expect("write");fixture(&f,&[],Some(&p)).await;let m=metadata(&repo(f.clone())).await;assert_eq!(m.legacy_parent_session_path.as_deref(),Some(p.as_str()));assert!(m.parent_session_id.is_none());std::fs::remove_dir_all(r).expect("cleanup")}

#[tokio::test] async fn opens_empty_legacy_data_only_branch(){let r=root("empty");let f=fs(&r);fixture(&f,&[],None).await;let repo=repo(f);let m=metadata(&repo).await;let s=repo.open(m,&BACKGROUND_CONTEXT).await.expect("open");assert!(s.find_entries(None,&BACKGROUND_CONTEXT).await.expect("entries").is_empty());assert!(s.get_value(&branch_tip("main"),&BACKGROUND_CONTEXT).await.expect("tip").is_none());assert!(s.get_value(&lane_state("main"),&BACKGROUND_CONTEXT).await.expect("state").is_none());assert!(s.get_value(&lane_config("main"),&BACKGROUND_CONTEXT).await.expect("config").is_none());s.close(&BACKGROUND_CONTEXT).await;std::fs::remove_dir_all(r).expect("cleanup")}

async fn config_session(label:&str, records:Vec<Value>)->Box<dyn Session>{let r=root(label);let f=fs(&r);fixture(&f,&records,None).await;let repo=repo(f);let m=metadata(&repo).await;repo.open(m,&BACKGROUND_CONTEXT).await.expect("open")}
#[tokio::test] async fn reparents_retained_child_through_config(){let s=config_session("reparent",vec![msg("one",None,"first",NOW+1000),model("model","one","anthropic","claude-sonnet-4-5",NOW+2000),thinking("think","model","high",NOW+3000),json!({"type":"active_tools_change","id":"tools","parentId":"think","timestamp":iso(NOW+4000),"activeToolNames":["read","bash"]}),msg("two",Some("tools"),"second",NOW+5000)]).await;let e=s.find_entries(Some(EntryQuery{order:Some(ScanOrder::Asc),..Default::default()}),&BACKGROUND_CONTEXT).await.expect("entries");assert_eq!(e.len(),2);assert_eq!(e[1].parent_id,e[0].id.clone().into());assert_eq!(s.get_value(&lane_config("main"),&BACKGROUND_CONTEXT).await.expect("config").expect("config").value["activeToolNames"],json!(["read","bash"]));s.close(&BACKGROUND_CONTEXT).await}
#[tokio::test] async fn selected_physical_branch_configuration_wins(){let s=config_session("selected",vec![msg("root",None,"first",NOW+1000),model("selected-model","root","anthropic","selected",NOW+2000),thinking("selected-thinking","selected-model","high",NOW+3000),model("abandoned-model","root","openai","abandoned",NOW+4000),msg("tip",Some("selected-thinking"),"second",NOW+5000)]).await;let c=s.get_value(&lane_config("main"),&BACKGROUND_CONTEXT).await.expect("config").expect("config");assert_eq!(c.value["model"],json!({"provider":"anthropic","modelId":"selected"}));s.close(&BACKGROUND_CONTEXT).await}
#[tokio::test] async fn missing_model_leaves_main_data_only(){let s=config_session("missing-model",vec![msg("root",None,"first",NOW+1000),thinking("thinking","root","high",NOW+2000),msg("tip",Some("thinking"),"second",NOW+3000)]).await;assert!(s.get_value(&lane_config("main"),&BACKGROUND_CONTEXT).await.expect("config").is_none());s.close(&BACKGROUND_CONTEXT).await}
#[tokio::test] async fn missing_thinking_leaves_main_data_only(){let s=config_session("missing-thinking",vec![msg("root",None,"first",NOW+1000),model("model","root","anthropic","selected",NOW+2000),msg("tip",Some("model"),"second",NOW+3000)]).await;assert!(s.get_value(&lane_config("main"),&BACKGROUND_CONTEXT).await.expect("config").is_none());s.close(&BACKGROUND_CONTEXT).await}
#[tokio::test] async fn trailing_configuration_resolves_main_tip(){let s=config_session("trailing",vec![msg("root",None,"first",NOW+1000),model("model","root","anthropic","claude-sonnet-4-5",NOW+2000),thinking("think","model","high",NOW+3000)]).await;let e=s.find_entries(Some(EntryQuery{order:Some(ScanOrder::Asc),..Default::default()}),&BACKGROUND_CONTEXT).await.expect("entries");assert_eq!(e.len(),1);assert_eq!(s.get_value(&branch_tip("main"),&BACKGROUND_CONTEXT).await.expect("tip").expect("tip").value,e[0].id);s.close(&BACKGROUND_CONTEXT).await}

#[tokio::test] async fn writes_zero_usage_adjustment_on_conversion(){let r=root("zero-adjustment");let f=fs(&r);let (path,_)=fixture(&f,&[],None).await;let st=JsonlStorage::open(JsonlStorageOptions{file_system:f,path,now:Some(Arc::new(||NOW))},&BACKGROUND_CONTEXT).await.expect("open");st.commit(vec![maho_agent::harness::session::types::Write::Value(maho_agent::harness::session::values::set_value(&session_name(),json!("Converted session")))],&BACKGROUND_CONTEXT).await.expect("commit");let rows=st.scan_usage(maho_agent::harness::session::types::UsageScan{order:Some(ScanOrder::Asc),..Default::default()},&BACKGROUND_CONTEXT).await.expect("usage");assert_eq!(rows.len(),1);assert!(rows[0].adjustment);assert_eq!(rows[0].usage.total_tokens,0);assert_eq!(rows[0].details,json!({"source":"v3-import"}).into());st.close(&BACKGROUND_CONTEXT).await;std::fs::remove_dir_all(r).expect("cleanup")}

#[tokio::test] async fn forks_closed_legacy_source_to_v4(){let r=root("fork-closed");let f=fs(&r);fixture(&f,&[msg("one",None,"fork me",NOW+1000),json!({"type":"label","id":"label","parentId":"one","timestamp":iso(NOW+2000),"targetId":"one","label":"Fork point"}),json!({"type":"session_info","id":"info","parentId":"label","timestamp":iso(NOW+3000),"name":"Imported fork"})],None).await;let repo=repo(f.clone());let m=metadata(&repo).await;let fork=repo.fork(m,maho_agent::harness::session::types::ForkOptions::Tree{id:Some("closed-fork".into())},&BACKGROUND_CONTEXT).await.expect("fork");assert_eq!(fork.metadata().id,"closed-fork");assert_eq!(fork.find_entries(None,&BACKGROUND_CONTEXT).await.expect("entries").len(),1);assert_eq!(fork.get_name(&BACKGROUND_CONTEXT).await.expect("name"),Some("Imported fork".into()));fork.close(&BACKGROUND_CONTEXT).await;std::fs::remove_dir_all(r).expect("cleanup")}
#[tokio::test] async fn forks_configured_legacy_at_main_tip(){let r=root("fork-tip");let f=fs(&r);fixture(&f,&[msg("root",None,"root",NOW),model("model","root","anthropic","claude-sonnet-4-5",NOW+1000),thinking("think","model","high",NOW+2000),msg("tip",Some("think"),"fork",NOW+3000)],None).await;let repo=repo(f);let m=metadata(&repo).await;let fork=repo.fork(m,maho_agent::harness::session::types::ForkOptions::Branch{id:Some("branch-fork".into()),branch:"main".into(),entry_id:None,position:None},&BACKGROUND_CONTEXT).await.expect("fork");assert_eq!(fork.find_entries(None,&BACKGROUND_CONTEXT).await.expect("entries").len(),2);fork.close(&BACKGROUND_CONTEXT).await;std::fs::remove_dir_all(r).expect("cleanup")}
#[tokio::test] async fn forks_configured_legacy_at_original_entry(){let r=root("fork-entry");let f=fs(&r);fixture(&f,&[msg("root",None,"root",NOW),model("model","root","anthropic","claude-sonnet-4-5",NOW+1000),thinking("think","model","high",NOW+2000),msg("message-1",Some("think"),"one",NOW+3000),msg("message-2",Some("message-1"),"two",NOW+4000),msg("message-3",Some("message-2"),"three",NOW+5000)],None).await;let repo=repo(f);let m=metadata(&repo).await;let fork=repo.fork(m,maho_agent::harness::session::types::ForkOptions::Branch{id:Some("entry-fork".into()),branch:"main".into(),entry_id:Some("message-2".into()),position:None},&BACKGROUND_CONTEXT).await.expect("fork");assert_eq!(fork.find_entries(None,&BACKGROUND_CONTEXT).await.expect("entries").len(),3);fork.close(&BACKGROUND_CONTEXT).await;std::fs::remove_dir_all(r).expect("cleanup")}
#[tokio::test] async fn rejects_open_legacy_until_commit(){let r=root("fork-open");let f=fs(&r);fixture(&f,&[msg("one",None,"fork me",NOW+1000)],None).await;let repo=repo(f);let m=metadata(&repo).await;let source=repo.open(m.clone(),&BACKGROUND_CONTEXT).await.expect("open");let result=repo.fork(m,maho_agent::harness::session::types::ForkOptions::Tree{id:Some("open-fork".into())},&BACKGROUND_CONTEXT).await;let err=match result { Ok(_) => panic!("open source"), Err(e) => e };assert!(err.message.contains("open legacy"));source.close(&BACKGROUND_CONTEXT).await;std::fs::remove_dir_all(r).expect("cleanup")}
#[tokio::test] async fn reports_embedded_usage_without_usage_rows(){let r=root("embedded-usage");let f=fs(&r);let (path,content)=fixture(&f,&[json!({"type":"message","id":"assistant","parentId":null,"timestamp":iso(NOW+1000),"message":{"role":"assistant","content":[{"type":"text","text":"answer"}],"api":"anthropic-messages","provider":"anthropic","model":"claude-sonnet-4-5","usage":{"input":1,"output":2,"cacheRead":3,"cacheWrite":4,"totalTokens":10,"cost":{"input":1,"output":2,"cacheRead":3,"cacheWrite":4,"total":10}},"stopReason":"stop","timestamp":NOW+1000}})],None).await;let st=JsonlStorage::open(JsonlStorageOptions{file_system:f,path:path.clone(),now:Some(Arc::new(||NOW))},&BACKGROUND_CONTEXT).await.expect("open");assert_eq!(st.get_stats(&BACKGROUND_CONTEXT).await.expect("stats").message_count,1);assert!(st.scan_usage(Default::default(),&BACKGROUND_CONTEXT).await.expect("usage").is_empty());st.close(&BACKGROUND_CONTEXT).await;assert_eq!(std::fs::read_to_string(path).expect("read"),content);std::fs::remove_dir_all(r).expect("cleanup")}
#[tokio::test] async fn converts_imported_usage_and_preserves_entries(){let r=root("convert-usage");let f=fs(&r);let (path,_)=fixture(&f,&[msg("one",None,"imported answer",NOW+1000)],None).await;let st=JsonlStorage::open(JsonlStorageOptions{file_system:f,path,now:Some(Arc::new(||NOW))},&BACKGROUND_CONTEXT).await.expect("open");let before=st.scan_entries(EntryScan{order:Some(ScanOrder::Asc),..Default::default()},&BACKGROUND_CONTEXT).await.expect("entries");st.commit(vec![maho_agent::harness::session::types::Write::Value(maho_agent::harness::session::values::set_value(&session_name(),json!("Converted session")))],&BACKGROUND_CONTEXT).await.expect("commit");assert_eq!(st.scan_entries(EntryScan{order:Some(ScanOrder::Asc),..Default::default()},&BACKGROUND_CONTEXT).await.expect("entries"),before);assert_eq!(st.scan_usage(Default::default(),&BACKGROUND_CONTEXT).await.expect("usage").len(),1);st.close(&BACKGROUND_CONTEXT).await;std::fs::remove_dir_all(r).expect("cleanup")}
#[tokio::test] async fn failed_conversion_preserves_source_and_state(){let r=root("convert-failure");let f=fs(&r);let (path,content)=fixture(&f,&[msg("one",None,"imported answer",NOW+1000)],None).await;let st=JsonlStorage::open(JsonlStorageOptions{file_system:f.clone(),path:path.clone(),now:Some(Arc::new(||NOW))},&BACKGROUND_CONTEXT).await.expect("open");let before=st.scan_entries(EntryScan{order:Some(ScanOrder::Asc),..Default::default()},&BACKGROUND_CONTEXT).await.expect("entries");let _=st.commit(vec![maho_agent::harness::session::types::Write::Value(maho_agent::harness::session::values::set_value(&session_name(),json!("Converted session")))],&BACKGROUND_CONTEXT).await;assert!(!before.is_empty());assert!(std::fs::read_to_string(path).expect("read").len()>=content.len());st.close(&BACKGROUND_CONTEXT).await;std::fs::remove_dir_all(r).expect("cleanup")}

#[tokio::test] async fn imports_session_info_as_name(){let s=config_session("session-info",vec![json!({"type":"session_info","id":"info","parentId":null,"timestamp":iso(NOW+1000),"name":"Imported session"})]).await;assert_eq!(s.get_name(&BACKGROUND_CONTEXT).await.expect("name"),Some("Imported session".into()));assert!(s.find_entries(None,&BACKGROUND_CONTEXT).await.expect("entries").is_empty());s.close(&BACKGROUND_CONTEXT).await}
#[tokio::test] async fn latest_session_info_resolves_discarded_tree(){let s=config_session("latest-info",vec![msg("one",None,"first",NOW+1000),json!({"type":"session_info","id":"i1","parentId":"one","timestamp":iso(NOW+2000),"name":"Earlier name"}),msg("two",Some("i1"),"second",NOW+3000),json!({"type":"session_info","id":"i2","parentId":"two","timestamp":iso(NOW+4000),"name":"Latest name"})]).await;let e=s.find_entries(None,&BACKGROUND_CONTEXT).await.expect("entries");assert_eq!(e.len(),2);assert_eq!(e[1].parent_id,e[0].id.clone().into());assert_eq!(s.get_name(&BACKGROUND_CONTEXT).await.expect("name"),Some("Latest name".into()));s.close(&BACKGROUND_CONTEXT).await}
